## 3. Result-Generation Logic (form data → recommendation)

Source: `client/src/lib/artificialDiscLogic.ts`

```typescript
export type DiscLevel = "cervical" | "lumbar";

export type ArtificialDiscInput = {
  age: string; spineRegion?: string; discLevel: string; affectedLevels: string; levels?: string;
  symptomDurationMonths: string;
  painScore: string; ndiScore?: string; symptoms?: string[];
  conservativeTherapyMonths: string; conservativeTherapies?: string[];
  imagingFindings: string[]; neurologicDeficits: string[]; comorbidities: string[];
  facetArthrosis: boolean; instability: boolean; osteoporosis: boolean;
  priorSpineSurgery: boolean; spondylolisthesis: boolean;
  activeInfection: boolean; medicallyUnfit?: boolean;
};

export type COR = "I" | "IIa" | "IIb" | "III";

export function getCORLabel(cor: COR): string {
  return { I: "Class I — Recommended", IIa: "Class IIa — Reasonable", IIb: "Class IIb — May Be Considered", III: "Class III — Not Recommended" }[cor];
}
export function getCORColor(cor: COR): string {
  return { I: "border-green-500 text-green-700", IIa: "border-blue-500 text-blue-700", IIb: "border-yellow-500 text-yellow-700", III: "border-red-500 text-red-700" }[cor];
}

export function assessArtificialDisc(input: ArtificialDiscInput) {
  const conservMonths = parseFloat(input.conservativeTherapyMonths) || 0;
  const ndi = parseFloat(input.ndiScore || '0') || 0;
  const levels = parseInt(input.levels || '1') || 1;

  const contraindications: string[] = [];
  if (input.activeInfection) contraindications.push("Active infection — absolute contraindication");
  if (input.osteoporosis) contraindications.push("Osteoporosis (T-score < -2.5) — contraindication for ADR");
  if (input.instability) contraindications.push("Spinal instability — ADR contraindicated; fusion preferred");
  if (input.facetArthrosis) contraindications.push("Significant facet arthrosis at affected level — contraindication for ADR");
  if (levels > 2) contraindications.push("More than 2 levels — exceeds FDA indication for most devices");
  if (input.medicallyUnfit) contraindications.push("Medically unfit for surgery");

  if (contraindications.length > 0) {
    return { recommendation: "Artificial Disc Replacement Contraindicated", cor: "III" as COR, loe: "B", urgency: "Contraindicated", rationale: ["One or more contraindications identified. Consider fusion instead."], contraindications, optimizationSteps: ["Consider spinal fusion as alternative", "Bone density scan to rule out osteoporosis", "Evaluate facet joint status on CT"] };
  }

  const rationale: string[] = [];
  const optimizationSteps: string[] = [];
  let cor: COR = "IIb";
  let urgency = "Elective";

  if (conservMonths >= 6 && ndi >= 30 && input.imagingFindings.includes("disc-herniation")) {
    cor = "I"; urgency = "Appropriate";
    rationale.push("DDD with radiculopathy, adequate conservative therapy failure, and no contraindications");
    rationale.push("FDA-approved device available for this indication");
    rationale.push("ADR preserves motion segment and may reduce adjacent segment disease vs. fusion");
  } else if (conservMonths >= 6 && ndi >= 20) {
    cor = "IIa"; urgency = "Reasonable";
    rationale.push("Adequate conservative therapy failure with functional impairment");
    rationale.push("ADR is a reasonable alternative to fusion in appropriate candidates");
  } else {
    cor = "IIb"; urgency = "Continue Conservative Therapy";
    rationale.push("Conservative therapy trial insufficient or criteria not fully met");
    optimizationSteps.push("Continue PT, medications, and injections for ≥6 months");
    optimizationSteps.push("Complete NDI functional assessment");
  }

  return { recommendation: cor === "I" ? "ADR Recommended" : cor === "IIa" ? "ADR Reasonable" : "ADR — Additional Criteria Needed", cor, loe: "A", urgency, rationale, contraindications, optimizationSteps };
}
